        }
        break;
      }
      case "neg":
        v = -this.eval(e.e, f, at);
        break;
      case "bin": {
        const l = this.eval(e.l, f, at);
        const r = this.eval(e.r, f, at);
        if (e.op === "/" && r === 0) throw new LogoError(`Dzielenie przez zero.`, at.line, at.col);
