    expect(ends("np +3")).toEqual([0, 3, 0]);
  });
  test("bad numbers", () => {
    for (const s of ["np 1e3", "np 0x10", "np NaN", "np Infinity"]) expect(err(s).error!.column).toBe(4);
  });
  test(".5 is a number", () => {
    expect(ends("np .5")).toEqual([0, 0.5, 0]);
  });
  test("exact comparisons", () => {
