  await loadProgram(String(source), m === "3d" ? "3d" : "2d", "silent", "program");
  const res = doRunInstant();
  fitView();
  await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
  view()?.request();
  await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
  return res;
}

