}
a { color: var(--accent); }
code, kbd, pre { font-family: var(--mono); font-size: 0.92em; }
kbd {
  border: 1px solid var(--border);
  border-bottom-width: 2px;
  border-radius: 5px;
  padding: 0 5px;
  background: var(--surface);
  white-space: nowrap;
}
.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}
.skip { position: absolute; left: -999px; top: 4px; z-index: 50; background: var(--surface); padding: 6px 10px; border-radius: 6px; }
.skip:focus { left: 8px; }
:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }
.muted { color: var(--muted); font-weight: normal; }
[hidden] { display: none !important; }

/* top bar */
.topbar {
  display: flex; align-items: center; gap: 16px;
  padding: 8px 16px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  position: sticky; top: 0; z-index: 10;
}
.brand { display: flex; align-items: center; gap: 8px; font-weight: 700; font-size: 18px; color: var(--text); text-decoration: none; letter-spacing: 0.2px; }
.mainnav { display: flex; gap: 4px; flex: 1; }
.mainnav a {
  padding: 6px 12px; border-radius: 8px; color: var(--text); text-decoration: none; font-weight: 500;
}
.mainnav a:hover { background: var(--surface-2); }
.mainnav a[aria-current="page"] { background: var(--accent-soft); color: var(--accent); }

/* buttons */
.btn {
  font: inherit; font-weight: 500;
  display: inline-flex; align-items: center; gap: 6px; justify-content: center;
  min-height: 36px; padding: 6px 12px;
  border: 1px solid var(--border); border-radius: 8px;
  background: var(--surface); color: var(--text);
  cursor: pointer; text-decoration: none; white-space: nowrap;
}
.btn:hover:not(:disabled) { background: var(--surface-2); }
.btn:disabled { opacity: 0.5; cursor: not-allowed; }
.btn.primary { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }
.btn.primary:hover:not(:disabled) { filter: brightness(1.08); background: var(--accent); }
.btn.ghost { background: transparent; border-color: transparent; }
.btn.ghost:hover { background: var(--surface-2); }
.btn.small { min-height: 30px; padding: 3px 10px; font-size: 13px; }
.btn.icon { min-width: 36px; padding: 6px 8px; }
.theme-label { font-size: 13px; color: var(--muted); }

