.page { flex: 1; display: flex; flex-direction: column; min-height: 0; }
#page-studio { padding: 10px 16px 16px; gap: 10px; }
.toolbar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.tb-group { display: flex; flex-wrap: wrap; gap: 2px; }
.seg { display: inline-flex; border: 1px solid var(--border); border-radius: 9px; overflow: hidden; background: var(--surface); }
