.ed-num.is-active { color: var(--accent); font-weight: 700; }
.ed-num.is-error { color: var(--danger); font-weight: 700; }
.ed-body { position: relative; flex: 1; overflow: hidden; }
.ed-hl, .ed-ta {
  margin: 0; padding: 10px 12px; font: inherit; line-height: inherit;
  white-space: pre; tab-size: 2; letter-spacing: 0;
}
.ed-hl { position: absolute; top: 0; left: 0; min-width: 100%; pointer-events: none; color: var(--text); }
