}
body[data-run="running"] #run-btn { box-shadow: 0 0 0 3px var(--accent-soft); }

.shortcuts-box { font-size: 14px; color: var(--muted); }
.shortcuts-box summary { cursor: pointer; width: max-content; }
.keys { display: grid; grid-template-columns: max-content 1fr; gap: 4px 14px; margin: 8px 0; }
.keys dt { text-align: right; }
